function maskSpriteSheet(img,columns){const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const g=c.getContext('2d');g.drawImage(img,0,0);const im=g.getImageData(0,0,c.width,c.height),d=im.data,w=c.width,h=c.height,seen=new Uint8Array(w*h),q=new Int32Array(w*h);let head=0,tail=0;function add(p){if(p<0||p>=w*h||seen[p])return;seen[p]=1;const k=p*4,r=d[k],gg=d[k+1],b=d[k+2],gray=Math.max(r,gg,b)-Math.min(r,gg,b)<35&&Math.min(r,gg,b)>85,chroma=r>210&&b>210&&gg<90;if(gray||chroma){q[tail++]=p;d[k+3]=0;}}for(let x=0;x<w;x++){add(x);add((h-1)*w+x);}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1);for(let col=1;col<columns;col++)add(y*w+Math.floor(col*w/columns));}while(head<tail){const p=q[head++],x=p%w;if(x>0)add(p-1);if(x<w-1)add(p+1);add(p-w);add(p+w);}g.putImageData(im,0,0);return c;}
