function reset(){heroes=names.map((name,i)=>({name,x:500+(i%3)*75,y:470+Math.floor(i/3)*85,hp:unlocked[i]?100:0,cd:0,attackCd:0,inv:0,warp:0,guard:0,face:0,locked:!unlocked[i]}));enemies=[];particles=[];shots=[];effects=[];zones=[];portals=null;aim=null;moveTarget=null;selected=0;wave=0;transition=0;paused=false;$('#pauseBanner').hidden=true;tutorial={move:0,switched:false,attack:false,special:false};updateUI();}
