function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}function bound(h){h.x=Math.max(135,Math.min(W-135,h.x));h.y=Math.max(190,Math.min(H-115,h.y));}
function nearest(h){return enemies.filter(e=>e.hp>0).sort((a,b)=>dist(h,a)-dist(h,b))[0];}
function say(s){$('#toast').textContent=s;$('#toast').classList.add('show');toastTime=3;}
function ring(x,y,color,r=50){effects.push({type:'ring',x,y,color,r,life:.5,max:.5});}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){let a=i/n*Math.PI*2;particles.push({x,y,vx:Math.cos(a)*(60+Math.random()*90),vy:Math.sin(a)*(60+Math.random()*90),color,life:.5,max:.5});}}
function slash(h,a,r=100,spin=false){effects.push({type:'slash',x:h.x,y:h.y,a,r,color:'#ffe4ae',spin,life:.3,max:.3});}
