function damage(e,n){if(e.dead)return;e.hp-=n;e.flash=.12;burst(e.x,e.y,'#f9dd9c',5);effects.push({type:'number',x:e.x,y:e.y-60,text:n,color:'#fff0b5',life:.65,max:.65});if(e.hp<=0){e.dead=true;burst(e.x,e.y,'#c9f69e',18);if(!e.dummy){const reward=e.boss?25:5;coins+=reward;saveProgress();effects.push({type:'number',x:e.x,y:e.y-25,text:'+'+reward+' קאמה',color:'#f5d98d',life:1.4,max:1.4});}}}
function hurt(h,n){if(h.hp<=0||h.inv>0)return;h.hp-=h.guard>0?Math.ceil(n*.25):n;h.inv=.45;burst(h.x,h.y,'#ff9d87',6);shake=.15;}
function switchHero(i){if(!heroes[i]||heroes[i].hp<=0||heroes[i].locked){say(heroes[i]?.locked?'עוד לא פגשתם את אדמאי':'הדמות נחה כרגע');return;}if(i!==selected){selected=i;tutorial.switched=true;ring(heroes[i].x,heroes[i].y,colors[i],50);updateUI();}}
function currentPower(i=selected){return POWERS[i].find(p=>p.id===equipped[i]);}
function updateUI(){document.querySelectorAll('.hero').forEach((b,i)=>{b.classList.toggle('active',selected===i);b.classList.toggle('locked',!unlocked[i]);b.setAttribute('aria-pressed',String(selected===i));b.disabled=!unlocked[i];b.querySelector('.health i').style.width=Math.max(0,heroes[i]?.hp??100)+'%';b.style.opacity=!unlocked[i] ? .45 : (heroes[i]?.hp<=0 ? .4 : 1);const state=b.querySelector('.unlock-state');if(state)state.textContent=unlocked[i]?'':'נפתח אחרי הבוס הראשון';});$('#specialName').textContent=currentPower().name;$('#coins').textContent=coins;$('#cooldown').style.width=(1-(heroes[selected]?.cd||0)/currentPower().cd)*100+'%';}
function attack(i=selected){if(!['training','battle'].includes(mode)||paused)return;const h=heroes[i];if(h.hp<=0||h.attackCd>0||h.locked)return;h.attackCd=(i===2||i===4)?.42:.52;const e=nearest(h),a=e?Math.atan2(e.y-h.y,e.x-h.x):h.face;h.face=a;if(i===2||i===4){slash(h,a,i===4?90:105);enemies.forEach(e=>{if(dist(h,e)<(i===4?105:120))damage(e,i===2&&h.guard>0?42:i===4?25:28);});}else{const speed=i===3?620:490,dmg=i===3?26:i===5?24:i===0?20:18;shots.push({x:h.x,y:h.y-28,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:i===3?1.25:.95,color:colors[i],leaf:i===1,arrow:i===3,fire:i===5,dmg,warp:0});ring(h.x+Math.cos(a)*24,h.y-28,colors[i],24);}if(i===selected)tutorial.attack=true;}
function lineDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
