 for(const e of effects){const t=1-e.life/e.max;ctx.save();ctx.globalAlpha=Math.min(1,e.life/e.max*2);if(e.type==='ring')circle(e.x,e.y,e.r*t+8,null,e.color);if(e.type==='slash'){ctx.translate(e.x,e.y-20);ctx.rotate(e.a);ctx.shadowBlur=18;ctx.shadowColor='#ffba61';for(let j=0;j<3;j++){ctx.beginPath();ctx.strokeStyle=j===0?'#fffbea':j===1?'#ffd16c':'#ff9a4955';ctx.lineWidth=11-j*3;const angle=e.spin?t*Math.PI*2:-1.1+t*2.2;ctx.arc(0,0,e.r-j*8,angle-.9,angle+.45);ctx.stroke();}}if(e.type==='beam'){ctx.shadowBlur=25;ctx.shadowColor=e.color;ctx.strokeStyle=e.color;ctx.lineWidth=24*(1-t)+3;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo(e.tx,e.ty);ctx.stroke();ctx.strokeStyle='#fffbd9';ctx.lineWidth=5;ctx.stroke();}if(e.type==='roots'){ctx.strokeStyle='#71b247';ctx.lineWidth=7;for(let k=0;k<5;k++){ctx.beginPath();ctx.moveTo(e.x+(k-2)*20,e.y+22);ctx.bezierCurveTo(e.x-45+k*18,e.y-10,e.x+40-k*20,e.y-35,e.x+(k-2)*15,e.y-60);ctx.stroke();}ctx.strokeStyle='#c3f47d';ctx.lineWidth=2;ctx.stroke();}if(e.type==='number'){ctx.font='bold 20px Arial';ctx.textAlign='center';ctx.fillStyle=e.color;ctx.strokeStyle='#16392a';ctx.lineWidth=3;ctx.strokeText(e.text,e.x,e.y-t*35);ctx.fillText(e.text,e.x,e.y-t*35);}ctx.restore();}
 for(const p of particles){ctx.globalAlpha=p.life/p.max;circle(p.x,p.y,3,p.color);}ctx.globalAlpha=1;
