let moveTarget=null,autoPaused=false;
function frame(t){const dt=Math.min((t-last)/1000||0,.035);last=t;tick(dt);draw();requestAnimationFrame(frame);}
function pauseGame(){if(!['training','battle'].includes(mode)||!$('#shopOverlay').hidden)return;paused=!paused;$('#pauseBanner').hidden=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'המשך':'עצירה');keys.clear();}
function resumeAuto(){if(autoPaused&&paused){autoPaused=false;pauseGame();}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD'].includes(e.code)){resumeAuto();moveTarget=null;}keys.add(e.code);if(e.repeat)return;if(/^Digit[1-6]$/.test(e.code))switchHero(Number(e.code.slice(-1))-1);if(e.code==='KeyJ')attack();if(e.code==='KeyE')special();if(e.code==='Space')dodge();if(e.code==='KeyB')openShop();if(e.code==='KeyP'||e.code==='Escape'){if(!$('#shopOverlay').hidden)closeShop();else{autoPaused=false;pauseGame();}}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
canvas.addEventListener('pointerdown',e=>{resumeAuto();if(!['battle','training'].includes(mode)||paused)return;const rect=canvas.getBoundingClientRect(),p={x:(e.clientX-rect.left)*devicePixelRatio/camera.scale+camera.ox,y:(e.clientY-rect.top)*devicePixelRatio/camera.scale+camera.oy};bound(p);aim={...p};moveTarget={...p};canvas.focus();});
document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>switchHero(Number(b.dataset.hero)));document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();resumeAuto();moveTarget=null;b.setPointerCapture(e.pointerId);keys.add(b.dataset.move);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.move);});$('#attack').onclick=()=>attack();$('#special').onclick=special;$('#dodge').onclick=dodge;$('#pause').onclick=()=>{autoPaused=false;pauseGame();};$('#resume').onclick=()=>{if(paused)pauseGame();autoPaused=false;canvas.focus();};$('#start').onclick=startTraining;$('#shopButton').onclick=openShop;
$('#help').onclick=()=>{if(!['training','battle'].includes(mode))return;const wasPaused=paused;paused=true;showPanel('איך משחקים?','חצים, WASD או לחיצה על הקרקע — תנועה<br>J — תקיפה · E — הכוח המצויד<br>רווח — התחמקות · 1 עד 6 — החלפה<br>B — חנות הכוחות · P — עצירה<br><br>יוגו: בחרי יעד על הקרקע, לחצי E, והיכנסי לשער.<br>האזור האדום מסמן מתקפת בוס — צאי ממנו בזמן!','חזרה למשחק',()=>{$('#overlay').hidden=true;paused=wasPaused;canvas.focus();});};
reset();requestAnimationFrame(frame);
window.gameState=()=>({mode,paused,selected,coins,equipped:[...equipped],owned:owned.map(x=>[...x]),unlocked:[...unlocked],world:{width:W,height:H,area:wave},heroes:heroes.map(h=>({name:h.name,hp:h.hp,x:h.x,y:h.y,locked:h.locked})),enemies:enemies.length,wave,portals:portals?{a:portals.a,b:portals.b,remaining:portals.life}:null,tutorial:{...tutorial}});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_game_state',description:'Read game phase, hero positions, health, coins, equipped powers, unlocked heroes and portal positions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.gameState()},{name:'select_hero',description:'Select an unlocked party hero numbered 1 to 6.',inputSchema:{type:'object',properties:{hero:{type:'integer',minimum:1,maximum:6}},required:['hero'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.hero)||input.hero<1||input.hero>6)throw Error('Hero must be between 1 and 6');switchHero(input.hero-1);return window.gameState();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
